KEYS = {"a": b"\xaa"*32, "b": b"\xbb"*32, "c": b"\xcc"*32}
POINT = (0.0, 0.0)
def dec(): return RangeDecision(sample_count=1, upper_bound=5.0, accepted=True)
def attest(i, t): return attest_observation(i, 1.0, 1.0, dec(), t, KEYS[i])

# empty input with max_skew -> existing ValueError from locate
try:
    locate_attested([], POINT, KEYS, max_skew=5); assert False
except ValueError as e: print("empty:", e)

# fewer than three records -> existing ValueError
try:
    locate_attested([attest("a",1), attest("b",2)], POINT, KEYS, max_skew=5); assert False
except ValueError as e: print("short:", e)

# invalid quorum/tolerance still raise
for kw in (dict(quorum=0), dict(quorum=2.5), dict(tolerance=-1)):
    try:
        locate_attested([attest("a",1),attest("b",2),attest("c",3)], POINT, KEYS, max_skew=5, **kw); assert False
